<!-- 文件作用：复用平台用户与组织成员详情的安全身份、真实分页记录和管理弹层；两种数据范围始终显式隔离。 -->
<template>
  <view class="person-center">
    <view v-if="error" class="error-box" @click="retry">{{error}} · 点击重试</view>
    <view v-if="loading&&!person" class="loading-line">正在读取管理资料…</view>
    <template v-if="person">
      <view class="person-identity"><image v-if="person.avatar" class="person-avatar" :src="assetUrl(person.avatar)" mode="aspectFill"/><Icon v-else name="user" :size="42"/><view class="person-copy"><text class="person-name">{{person.nickname||'未设置昵称'}}</text><text class="person-role">{{isPlatform&&platform?platformRoleName(platform.user):member?.management_role==='owner'?'俱乐部负责人':member?.management_role==='deputy'?'俱乐部副管理员':member?.membership.status==='active'?'认证成员':'待审核成员'}}</text><button class="person-id text-btn" @click="copyID"><text class="person-id-value">ID: {{person.id}}</text><Icon name="copy" :size="13"/></button><text v-if="platform" class="record-note">{{platform.user.phone_masked||'未验证手机号'}} · {{platform.user.status==='frozen'?'已冻结':'正常'}}</text></view></view>
      <view v-if="isPlatform&&platform" class="person-section"><view class="section-heading"><text class="section-title">基础资料</text><button v-if="permissions.can_edit" class="text-btn" :disabled="busy" @click="openEditor">编辑<Icon name="edit" :size="15"/></button></view><view class="person-field"><text class="record-note">昵称</text><text>{{platform.user.nickname}}</text></view><view class="person-field"><text class="record-note">手机号</text><text>{{platform.user.phone_masked||'未验证'}}</text></view><view class="person-field"><text class="record-note">注册时间</text><text>{{time(platform.user.created_at)||'—'}}</text></view></view>
      <view v-if="member" class="person-section"><text class="record-note scope-note">仅显示该成员在本俱乐部的数据，累计收入不代表个人可提现余额。</text><view class="person-metrics"><view class="person-metric"><text class="record-note">累计结算收入</text><text>{{currency(member.scope_finance.settled_income_cents)}}</text></view><view class="person-metric"><text class="record-note">进行中</text><text>{{currency(member.scope_finance.ongoing_cents)}}</text></view><view class="person-metric"><text class="record-note">结算中</text><text>{{currency(member.scope_finance.settling_cents)}}</text></view><view class="person-metric"><text class="record-note">托管押金</text><text>{{currency(member.scope_finance.club_deposit_cents)}}</text></view><view class="person-metric"><text class="record-note">押金退还中</text><text>{{currency(member.scope_finance.club_deposit_refunding_cents)}}</text></view></view></view>
      <view class="person-actions"><button v-if="permissions.can_send_message" class="btn btn-secondary btn-small" :disabled="busy" @click="openMessage">发送站内消息</button><button v-if="platform&&permissions.can_edit&&person.id!==state.user?.id" class="text-btn" :disabled="busy" @click="toggleFrozen">{{platform.user.status==='frozen'?'解除冻结':'冻结账号'}}</button></view>
      <button v-if="permissions.can_manage_admins&&(isPlatform?isPlatformRoot(state.user):true)" class="person-setting" :disabled="busy" @click="toggleDeputy"><Icon name="shield" :size="21"/><text class="person-setting-copy">{{isPlatform?'平台副管理员':'俱乐部副管理员'}}<text class="record-note">{{isDeputy?'已设置，点击撤销':'点击授予管理权限'}}</text></text><Icon name="arrow" :size="14"/></button>
      <view v-if="member&&permissions.can_edit&&member.management_role!=='owner'" class="person-actions"><button v-if="member.membership.status==='pending'" class="text-btn" :disabled="busy" @click="reviewMember('active')">通过成员认证</button><button v-if="member.membership.status==='pending'" class="text-btn" :disabled="busy" @click="reviewMember('rejected')">拒绝申请</button><button v-if="member.membership.status==='active'" class="text-btn" :disabled="busy" @click="reviewMember('removed')">移除成员</button></view>
      <view class="person-tabs"><button v-for="item in tabs" :key="item.id" :class="['person-tab',{selected:tab===item.id}]" @click="selectTab(item.id)">{{item.label}}</button></view>
      <view v-if="tab==='funds'">
        <view v-if="isPlatform" class="person-metrics"><view v-for="item in walletMetrics" :key="item.key" class="person-metric"><text class="record-note">{{item.label}}</text><text>{{currency(wallet?.[item.key])}}</text></view></view><text v-if="walletError" class="record-note">{{walletError}}</text>
        <view v-for="item in entries" :key="item.id" class="record-row"><view class="record-copy"><text>{{item.note||walletKind(item.kind)}}</text><text class="record-note">{{time(item.created_at)}}{{'scope' in item?' · 本俱乐部':''}}</text></view><text class="record-amount">{{currency(item.amount_cents)}}</text></view>
      </view>
      <view v-else-if="tab==='orders'"><view v-if="isPlatform" class="record-filters"><button v-for="item in orderRoles" :key="item.id" :class="['text-btn',{muted:orderRole!==item.id}]" @click="selectOrderRole(item.id)">{{item.label}}</button></view><view v-for="item in orders" :key="item.id" class="record-row"><view class="record-copy"><text>{{item.title}}</text><text class="record-note">{{item.order_no}} · {{statusLabel(item.status)}} · {{time(item.created_at)}}</text><text v-if="!isPlatform" class="record-note">本俱乐部订单 · {{item.game_name}}</text></view><text class="record-amount">{{currency(item.amount_cents)}}</text></view></view>
      <view v-else><view v-for="item in moderations" :key="item.id" class="record-row"><view class="record-copy"><text>{{item.field_label||'图文审核'}}</text><text class="record-note">{{moderationStatus(item.status)}} · {{time(item.created_at)}}</text><text v-if="item.reason" class="record-note">{{item.reason}}</text></view></view></view>
      <text v-if="!recordsLoading&&!recordCount&&!recordError" class="record-empty">暂无{{tab==='funds'?'资金明细':tab==='orders'?'订单':'审核记录'}}</text><ListLoadState :loading="recordsLoading" :has-more="hasMore" :error="recordError" @retry="retryRecords"/>
    </template>
    <text v-else-if="!loading&&!error" class="subtle-note">{{state.user?'暂无可访问的管理资料':'请登录后查看管理资料'}}</text>
    <UniPopup ref="popup" type="bottom" background-color="transparent" :safe-area="false" @change="popupChanged"><view class="person-sheet"><view class="section-heading"><text class="section-title">{{dialog==='edit'?'编辑基础资料':'发送站内消息'}}</text><button class="text-btn" :disabled="busy||uploading" aria-label="关闭" @click="closeDialog()"><Icon name="close" :size="22"/></button></view><scroll-view scroll-y class="person-sheet-scroll">
      <template v-if="dialog==='edit'"><view class="form-section"><view class="field"><text class="field-label">昵称 · 2—24字</text><input v-model="form.nickname" class="input" maxlength="24" placeholder="填写用户昵称"/></view><view class="field"><text class="field-label">简介 · 最多300字</text><textarea v-model="form.bio" class="input person-textarea" maxlength="300" placeholder="填写个人简介"/></view><view class="person-upload"><image v-if="form.avatar" class="person-avatar" :src="assetUrl(form.avatar)" mode="aspectFill"/><button class="text-btn" :disabled="uploading||busy" @click="upload('avatar')">{{uploading?'图片处理中…':'更换头像 · 1:1'}}</button></view><button class="text-btn" :disabled="uploading||busy" @click="upload('profile_cover')">更换主页封面 · 16:9</button><image v-if="form.profile_cover" class="person-cover-preview" :src="assetUrl(form.profile_cover)" mode="aspectFill"/></view></template>
      <template v-else-if="dialog==='message'"><text class="record-note">只发送给 {{person?.nickname||'当前目标用户'}}</text><view class="form-section"><view class="field"><text class="field-label">标题 · 1—60字</text><input v-model="message.title" class="input" maxlength="60" placeholder="消息标题"/></view><view class="field"><text class="field-label">内容 · 1—5000字</text><textarea v-model="message.body" class="input person-textarea" maxlength="5000" placeholder="填写站内消息内容"/></view></view></template>
    </scroll-view><text v-if="formError" class="error-box">{{formError}}</text><view class="action-footer"><button class="text-btn" :disabled="busy||uploading" @click="closeDialog()">取消</button><button class="btn" :disabled="busy||uploading" @click="submitDialog">{{busy?'处理中…':dialog==='edit'?'保存资料':'发送消息'}}</button></view></view></UniPopup>
  </view>
</template>
<script setup lang="ts">
import { computed,nextTick,reactive,ref,watch } from 'vue'
import { onShow,onHide,onUnload } from '@dcloudio/uni-app'
import UniPopup from '@dcloudio/uni-ui/lib/uni-popup/uni-popup.vue'
import Icon from './Icon.vue'
import ListLoadState from './ListLoadState.vue'
import { getManagedUser,updateManagedUser,setPlatformDeputy,sendManagedUserMessage,getManagedUserWallet,listManagedUserEntries,listManagedUserOrders,listManagedUserModeration,getManagedMember,setClubDeputy,sendManagedMemberMessage,listManagedMemberOrders,listManagedMemberEntries,listManagedMemberModeration } from '../api/management.api'
import { moderateResource } from '../api/admin.api'
import { reviewClubMember } from '../api/clubs.api'
import { token,errorMessage,errorStatus,isCancelled } from '../api/client'
import { state,init,sessionRevision } from '../lib/store'
import { isPlatformRoot,platformRoleName } from '../lib/management-permissions'
import { assetUrl,notify,time,statusLabel } from '../lib/format'
import { chooseUploadImage } from '../lib/media'
import { appendUniqueRows } from '../lib/list-page'
import { walletKind } from '../lib/wallet'
import { useNativePageRefresh } from '../lib/native-page-refresh'
import type { Order } from '../types/models'
import type { Wallet,WalletEntry } from '../types/wallet'
import type { ManagedUserDetail,ManagedMemberDetail,ManagementPage,ModerationRecord,ScopedMemberEntry } from '../types/management'
type Tab='funds'|'orders'|'moderation'
const props=defineProps<{scope:'platform'|'club';targetId:string;clubId?:string}>()
const isPlatform=computed(()=>props.scope==='platform'),platform=ref<ManagedUserDetail|null>(null),member=ref<ManagedMemberDetail|null>(null),wallet=ref<Wallet|null>(null),walletError=ref('')
const person=computed(()=>platform.value?.user||member.value?.user),permissions=computed(()=>platform.value?.permissions||member.value?.permissions||{can_edit:false,can_manage_admins:false,can_send_message:false})
const isDeputy=computed(()=>isPlatform.value?platform.value?.user.platform_admin_role==='deputy':member.value?.management_role==='deputy')
const tab=ref<Tab>(props.scope==='platform'?'funds':'orders'),orderRole=ref<'all'|'buyer'|'provider'>('all'),entries=ref<Array<WalletEntry|ScopedMemberEntry>>([]),orders=ref<Order[]>([]),moderations=ref<ModerationRecord[]>([])
const loading=ref(false),error=ref(''),recordsLoading=ref(false),recordError=ref(''),hasMore=ref(false),busy=ref(false),uploading=ref(false),dialog=ref<'edit'|'message'|null>(null),formError=ref('')
const form=reactive({nickname:'',bio:'',avatar:'',profile_cover:''}),message=reactive({title:'',body:''}),popup=ref<{open:(type?:string)=>void;close:()=>void;showPopup?:boolean}|null>(null)
const tabs=computed<Array<{id:Tab;label:string}>>(()=>isPlatform.value?[{id:'funds',label:'资金'},{id:'orders',label:'订单'},{id:'moderation',label:'AI审核'}]:[{id:'orders',label:'本俱乐部订单'},{id:'funds',label:'资金明细'},{id:'moderation',label:'图文审核'}])
const orderRoles=[{id:'all',label:'全部'},{id:'buyer',label:'买方'},{id:'provider',label:'打手'}] as const
const walletMetrics:Array<{key:keyof Wallet;label:string}>=[{key:'spendable_cents',label:'账户余额'},{key:'available_cents',label:'可提现'},{key:'recharge_cents',label:'充值仅消费'},{key:'ongoing_cents',label:'进行中'},{key:'settling_cents',label:'结算中'},{key:'withdrawal_frozen_cents',label:'提现中'}]
const recordCount=computed(()=>tab.value==='funds'?entries.value.length:tab.value==='orders'?orders.value.length:moderations.value.length)
let visible=false,disposed=false,loadVersion=0,recordVersion=0,actionVersion=0,uploadVersion=0,nextOffset=0,failedAppend=false,closingPopup=false
/** 捕获具体身份、管理范围和目标，迟到结果不能回填其他成员。 */
function stamp():string{return JSON.stringify([state.user?.id,state.user?.role,state.user?.platform_admin_role,state.user?.status,token(),sessionRevision(),props.scope,props.clubId,props.targetId])}
/** 当前操作者仍有基础身份资格，具体组织管理权继续由服务端返回及每次API鉴权。 */
function actorEligible():boolean{return !!state.user&&state.user.status!=='frozen'&&(!isPlatform.value||state.user.role==='admin')}
/** 管理动作绑定当前服务端能力，撤销组织权限后旧确认与上传不能沿用先前授权。 */
function actionStamp():string{return JSON.stringify([stamp(),permissions.value.can_edit,permissions.value.can_manage_admins,permissions.value.can_send_message])}
/** 动作回调同时核对身份和权限；原生选图可放宽临时隐藏。 */
function currentAction(owner:string,hidden=false):boolean{return !disposed&&(hidden||visible)&&actorEligible()&&owner===actionStamp()}
/** 判断请求仍属于当前可访问目标；上传允许原生选图短暂隐藏。 */
function current(owner:string,hidden=false):boolean{return !disposed&&(hidden||visible)&&actorEligible()&&owner===stamp()}
/** 金额仅展示有效整数分，缺失不伪造为零。 */
function currency(value:unknown):string{return typeof value==='number'&&Number.isSafeInteger(value)?'¥'+(value/100).toFixed(2):'—'}
/** 将已知审核状态转为安全可读文案。 */
function moderationStatus(value:string):string{return ({ai_pending:'AI待审核',ai_processing:'AI审核中',manual_pending:'待人工审核',allowed:'已通过',rejected:'未通过',superseded:'内容已更新'} as Record<string,string>)[value]||value}
/** 清除旧范围记录；分页偏移始终跟随服务端原始条数。 */
function clearRecords():void{recordVersion++;entries.value=[];orders.value=[];moderations.value=[];nextOffset=0;hasMore.value=false;recordsLoading.value=false;recordError.value='';failedAppend=false}
/** 初次或下拉读取详情和权限，再读取当前页签；所有读取均为GET。 */
async function load():Promise<void>{if(!visible||disposed||!props.targetId||!isPlatform.value&&!props.clubId)return;const version=++loadVersion,owner=stamp();loading.value=true;error.value='';try{await init();if(!current(owner)||version!==loadVersion)return;if(!state.user||isPlatform.value&&state.user.role!=='admin'){platform.value=null;member.value=null;clearRecords();return}if(isPlatform.value){const value=await getManagedUser(props.targetId);if(!current(owner)||version!==loadVersion)return;platform.value=value;member.value=null;try{const funds=await getManagedUserWallet(props.targetId);if(current(owner)&&version===loadVersion){wallet.value=funds;walletError.value=''}}catch(err){if(current(owner)&&version===loadVersion){if([401,403].includes(errorStatus(err)||0))throw err;walletError.value=errorMessage(err)}}}else{const value=await getManagedMember(props.clubId!,props.targetId);if(!current(owner)||version!==loadVersion)return;member.value=value;platform.value=null}if(current(owner)&&version===loadVersion)await loadRecords()}catch(err){if(current(owner)&&version===loadVersion){error.value=errorMessage(err);if([401,403,404].includes(errorStatus(err)||0)){platform.value=null;member.value=null;wallet.value=null;clearRecords();closeDialog(true)}}}finally{if(version===loadVersion)loading.value=false}}
/** 当前页签只读分页；失败记录原刷新/追加方向，旧筛选回包不覆盖新记录。 */
async function loadRecords(append=false):Promise<void>{if(!visible||!person.value||recordsLoading.value||append&&!hasMore.value)return;const version=++recordVersion,owner=stamp(),selected=tab.value,role=orderRole.value,offset=append?nextOffset:0;recordsLoading.value=true;recordError.value='';try{const query={limit:20,offset};let result:ManagementPage<WalletEntry|ScopedMemberEntry|Order|ModerationRecord>;if(selected==='funds')result=isPlatform.value?await listManagedUserEntries(props.targetId,query):await listManagedMemberEntries(props.clubId!,props.targetId,query);else if(selected==='orders')result=isPlatform.value?await listManagedUserOrders(props.targetId,{...query,role}):await listManagedMemberOrders(props.clubId!,props.targetId,query);else result=isPlatform.value?await listManagedUserModeration(props.targetId,query):await listManagedMemberModeration(props.clubId!,props.targetId,query);if(!current(owner)||version!==recordVersion||selected!==tab.value||role!==orderRole.value)return;if(selected==='funds')entries.value=appendUniqueRows(append?entries.value:[],result.items as Array<WalletEntry|ScopedMemberEntry>);else if(selected==='orders')orders.value=appendUniqueRows(append?orders.value:[],result.items as Order[]);else moderations.value=appendUniqueRows(append?moderations.value:[],result.items as ModerationRecord[]);nextOffset=offset+result.items.length;hasMore.value=result.has_more;failedAppend=false}catch(err){if(current(owner)&&version===recordVersion){recordError.value=errorMessage(err);failedAppend=append;if([401,403].includes(errorStatus(err)||0)){platform.value=null;member.value=null;wallet.value=null;walletError.value='';clearRecords();closeDialog(true);error.value=errorMessage(err)}}}finally{if(version===recordVersion)recordsLoading.value=false}}
/** 重试原分页动作，不把失败的刷新错误变成下一页。 */
async function retryRecords():Promise<void>{await loadRecords(failedAppend)}
/** 初始化错误重读权限及详情，不重放任何写操作。 */
async function retry():Promise<void>{if(!busy.value&&!uploading.value)await load()}
/** 切换页签时立即废弃旧页签回包与偏移。 */
function selectTab(value:Tab):void{if(value===tab.value)return;tab.value=value;clearRecords();void loadRecords()}
/** 买卖身份切换只作用平台目标用户订单查询。 */
function selectOrderRole(value:'all'|'buyer'|'provider'):void{if(value===orderRole.value)return;orderRole.value=value;clearRecords();void loadRecords()}
/** 复制公开ID，不复制微信身份或手机号。 */
function copyID():void{if(!person.value)return;const owner=stamp();uni.setClipboardData({data:person.value.id,success(){if(current(owner))notify('用户ID已复制')},fail(err){if(current(owner))notify(err)}})}
/** 在官方弹层内打开已授权的公开资料草稿。 */
function openEditor():void{if(!visible||!actorEligible()||!platform.value||!permissions.value.can_edit||busy.value)return;Object.assign(form,{nickname:platform.value.user.nickname||'',bio:platform.value.user.bio||'',avatar:platform.value.user.avatar||'',profile_cover:platform.value.user.profile_cover||''});formError.value='';dialog.value='edit';void showDialog()}
/** 定向消息始终绑定当前目标，表单不允许填写接收账号。 */
function openMessage():void{if(!visible||!actorEligible()||!permissions.value.can_send_message||busy.value)return;message.title='';message.body='';formError.value='';dialog.value='message';void showDialog()}
/** 等待弹层挂载后打开，避免页面普通文档流模拟弹框。 */
async function showDialog():Promise<void>{const owner=actionStamp(),kind=dialog.value,version=actionVersion;await nextTick();if(currentAction(owner)&&kind===dialog.value&&version===actionVersion&&dialog.value&&!closingPopup)popup.value?.open('bottom')}
/** 关闭时清理消息和编辑草稿，提交中禁止重复关闭。 */
function closeDialog(force=false):void{if(!force&&(busy.value||uploading.value))return;dialog.value=null;if(popup.value?.showPopup){closingPopup=true;popup.value.close()}else closingPopup=false;Object.assign(message,{title:'',body:''});Object.assign(form,{nickname:'',bio:'',avatar:'',profile_cover:''});formError.value=''}
/** 迟到关闭事件只确认旧动画，不能清理随后打开的表单。 */
function popupChanged(event:{show:boolean}):void{if(event.show){closingPopup=false;return}if(closingPopup){closingPopup=false;if(dialog.value)void showDialog();return}closeDialog(true);closingPopup=false}
/** 官方裁剪压缩上传，原生选图短暂隐藏不丢草稿，跨账号不回填。 */
async function upload(purpose:'avatar'|'profile_cover'):Promise<void>{if(!visible||!actorEligible()||!permissions.value.can_edit||busy.value||uploading.value||dialog.value!=='edit')return;const owner=actionStamp(),version=++uploadVersion;uploading.value=true;try{const url=await chooseUploadImage(purpose);if(version===uploadVersion&&currentAction(owner,true)&&dialog.value==='edit'&&url)form[purpose]=url}catch(err){if(version===uploadVersion&&currentAction(owner,true)&&!isCancelled(err))notify(err)}finally{if(version===uploadVersion){uploading.value=false;if(currentAction(owner)&&dialog.value)void showDialog()}}}
/** 表单保存与站内消息提交保留原目标；隐藏或切号后的回调不能影响其他账号。 */
async function submitDialog():Promise<void>{if(!visible||!actorEligible()||busy.value||uploading.value||!dialog.value)return;const owner=actionStamp(),version=++actionVersion,kind=dialog.value;formError.value='';if(kind==='edit'&&(!platform.value||!permissions.value.can_edit)||kind==='message'&&!permissions.value.can_send_message)return;const nickname=form.nickname.trim(),bio=form.bio.trim(),title=message.title.trim(),body=message.body.trim();if(kind==='edit'&&(Array.from(nickname).length<2||Array.from(nickname).length>24||Array.from(bio).length>300)){formError.value='昵称需2—24字，简介最多300字';return}if(kind==='message'&&(!title||Array.from(title).length>60||!body||Array.from(body).length>5000)){formError.value='标题需1—60字，内容需1—5000字';return}busy.value=true;try{if(kind==='edit')await updateManagedUser(props.targetId,{nickname,bio,avatar:form.avatar,profile_cover:form.profile_cover});else if(isPlatform.value)await sendManagedUserMessage(props.targetId,{title,body});else await sendManagedMemberMessage(props.clubId!,props.targetId,{title,body});if(!currentAction(owner)||version!==actionVersion)return;closeDialog(true);notify(kind==='edit'?'资料已保存，图文进入审核':'站内消息已发送');await load()}catch(err){if(currentAction(owner)&&version===actionVersion)formError.value=errorMessage(err)}finally{if(version===actionVersion)busy.value=false}}
/** 统一确认管理写操作，确认中身份或目标变化则取消旧操作。 */
async function confirmAction(title:string,content:string,action:()=>Promise<unknown>):Promise<void>{if(busy.value||uploading.value||!visible||!actorEligible())return;const owner=actionStamp(),version=++actionVersion;busy.value=true;try{const result=await uni.showModal({title,content,confirmText:'确认',cancelText:'取消'});if(!result.confirm||!currentAction(owner)||version!==actionVersion)return;await action();if(currentAction(owner)&&version===actionVersion){notify('操作已保存');await load()}}catch(err){if(currentAction(owner)&&version===actionVersion)notify(err)}finally{if(version===actionVersion)busy.value=false}}
/** 冻结操作仅针对服务端允许编辑的其他账号，不修改资金。 */
async function toggleFrozen():Promise<void>{if(!platform.value||!permissions.value.can_edit||person.value?.id===state.user?.id)return;const target=props.targetId,frozen=platform.value.user.status==='frozen';await confirmAction(frozen?'解除冻结':'冻结账号','确认'+(frozen?'恢复':'冻结')+'该账号？',()=>moderateResource('users',target,{status:frozen?'active':'frozen'}))}
/** 根或组织负责人依服务端授权授撤副管理员，副管理员无此入口。 */
async function toggleDeputy():Promise<void>{if(!permissions.value.can_manage_admins||isPlatform.value&&!isPlatformRoot(state.user))return;const target=props.targetId,clubID=props.clubId,enabled=!isDeputy.value;await confirmAction(enabled?'授予副管理员':'撤销副管理员','确认'+(enabled?'授予':'撤销')+'该用户的'+(isPlatform.value?'平台':'本俱乐部')+'管理权限？',()=>isPlatform.value?setPlatformDeputy(target,enabled):setClubDeputy(clubID!,target,enabled))}
/** 成员审核仅作用当前组织，考核通过由管理者明确确认，不修改全局身份。 */
async function reviewMember(status:'active'|'rejected'|'removed'):Promise<void>{if(!member.value||!permissions.value.can_edit||member.value.management_role==='owner')return;const clubID=props.clubId!,target=props.targetId;await confirmAction('成员审核',status==='active'?'确认该成员已完成加入条件及必要考核？':status==='removed'?'确认移除该成员？':'确认拒绝该入会申请？',()=>reviewClubMember(clubID,target,{status,assessment_passed:status==='active',review_note:''}))}
/** 账号、目标变化时立即撤销旧请求、权限、消息与所有私有资金数据。 */
function reset():void{loadVersion++;recordVersion++;actionVersion++;uploadVersion++;uploading.value=false;platform.value=null;member.value=null;wallet.value=null;walletError.value='';loading.value=false;busy.value=false;clearRecords();closeDialog(true);if(visible)void load()}
/** 原生选图保留同账号编辑草稿，普通离页则清除表单与未完成读取。 */
function hide():void{visible=false;loadVersion++;recordVersion++;actionVersion++;busy.value=false;loading.value=false;recordsLoading.value=false;if(!uploading.value)closeDialog(true)}
watch([()=>props.scope,()=>props.targetId,()=>props.clubId,()=>state.user?.id,()=>state.user?.role,()=>state.user?.platform_admin_role,()=>state.user?.status,sessionRevision],reset,{flush:'sync'})
/** 当前组织能力变化只撤销旧操作和本地草稿；全部失权时清空私有显示，不修改服务器资料。 */
watch(()=>[permissions.value.can_edit,permissions.value.can_manage_admins,permissions.value.can_send_message].join('|'),()=>{actionVersion++;uploadVersion++;busy.value=false;uploading.value=false;closeDialog(true);if(!permissions.value.can_edit&&!permissions.value.can_manage_admins&&!permissions.value.can_send_message){loadVersion++;platform.value=null;member.value=null;wallet.value=null;walletError.value='';loading.value=false;clearRecords()}},{flush:'sync'})
onShow(()=>{visible=true;void load();if(dialog.value)void showDialog()});onHide(hide);onUnload(()=>{disposed=true;hide();reset()})
useNativePageRefresh({refresh:load,more:()=>recordError.value?retryRecords():loadRecords(true),blocked:()=>busy.value||uploading.value||loading.value||recordsLoading.value||!!dialog.value,context:()=>[stamp(),tab.value,orderRole.value]})
</script>
